package com.example.corejava.examples;
import com.example.corejava.domain.*; import com.example.corejava.repository.*; import com.example.corejava.service.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
public final class CourseDemo { public static void main(String[] args)throws Exception { Product laptop=new Product(1L,"Laptop",new BigDecimal("999.99"),3); Product mouse=new Product(2L,"Mouse",new BigDecimal("25.00"),20); System.out.println("Price + tax: "+new PriceCalculator().tax(new PriceCalculator().total(mouse.price(),10))); PaymentRouter router=new PaymentRouter();System.out.println("Payment authorized: "+router.processPayment(new CreditCardPayment(new BigDecimal("50"),"****1234"))); InMemoryUserRepository repo=new InMemoryUserRepository();repo.save(new Customer(1L,"user@example.com"));System.out.println("Optional user: "+repo.findById(1L).map(Customer::email).orElse("missing")); Order order=new Order(100L,1L,List.of(new OrderItem(laptop,1),new OrderItem(mouse,2)),OrderStatus.PENDING,Instant.now());System.out.println("Order total: "+order.total());AnalyticsService analytics=new AnalyticsService();System.out.println("Filtered products: "+analytics.filter(List.of(laptop,mouse),p->p.price().compareTo(new BigDecimal("50"))<0));System.out.println("ETA: "+LocalDateTime.now().plusDays(5));}}
